function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // trophy
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20 * Math.sin(t), H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2 - 30);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t), H/2 - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2 - 10);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t) - 10, H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2 - 10);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t) + 10, H/2 + 10);
  ctx.stroke();

  // confetti
  ctx.beginPath();
  ctx.arc(W/2 - 30 + 10 * Math.sin(2 * t), H/2 - 100 + 10 * Math.cos(2 * t), 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 10 + 10 * Math.sin(2 * t + Math.PI / 2), H/2 - 120 + 10 * Math.cos(2 * t + Math.PI / 2), 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 10 + 10 * Math.sin(2 * t + Math.PI), H/2 - 140 + 10 * Math.cos(2 * t + Math.PI), 5, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
